package dev.zomboid.decor.needs;
import dev.zomboid.decor.R;import java.util.*;
public final class Needs {
 static final String PREFIX="DDNeeds6";static final Map<Object,Cycle> STATES=new WeakHashMap<>();static final Map<Object,Object> SEATS=new WeakHashMap<>();static final Set<Object> SYNCED=Collections.newSetFromMap(new WeakHashMap<>());static boolean warned,aidChecked;static Class<?> aid;static final Map<Object,Object> PREVIOUS_POSE=new WeakHashMap<>();static final Set<Object> FORCED=Collections.newSetFromMap(new WeakHashMap<>());
 static int value(Object tag,String key,int fallback){return R.yes(R.call(tag,"contains",PREFIX+key))?((Number)R.call(tag,"getInt",PREFIX+key)).intValue():fallback;}
 public static Cycle get(Object p){return STATES.computeIfAbsent(p,k->{Object tag=R.call(p,"getPersistentData");Cycle c=new Cycle();c.remaining=Math.max(1,Math.min(12000,value(tag,"Clock",12000)));c.kind=Math.max(0,Math.min(2,value(tag,"Kind",0)));c.grace=Math.max(1,Math.min(2400,value(tag,"Grace",2400)));c.nextKind=value(tag,"Next",1)==2?2:1;c.held=R.yes(R.call(tag,"getBoolean",PREFIX+"Held"));return c;});}
 static void save(Object p,Cycle c){Object tag=R.call(p,"getPersistentData");R.call(tag,"putInt",PREFIX+"Clock",c.remaining);R.call(tag,"putInt",PREFIX+"Kind",c.kind);R.call(tag,"putInt",PREFIX+"Grace",c.grace);R.call(tag,"putInt",PREFIX+"Next",c.nextKind);R.call(tag,"putBoolean",PREFIX+"Held",c.held);}
 public static void text(Object p,String key,boolean bar,Object...args){R.call(p,"displayClientMessage",R.call(R.type("net.minecraft.network.chat.Component"),"translatable","doomsday.needs."+key,args),bar);}
 static void prompt(Object p,Cycle c){text(p,c.kind==1?"pee_due":"poop_due",false);text(p,"hint",true);Object line=R.call(R.type("net.minecraft.network.chat.Component"),"translatable","doomsday.needs.hold_button",new Object[0]);Object click=R.make("net.minecraft.network.chat.ClickEvent",R.get(R.type("net.minecraft.network.chat.ClickEvent$Action"),"RUN_COMMAND"),"/necesidades aguantar");Object style=R.call(R.get(R.type("net.minecraft.network.chat.Style"),"EMPTY"),"withClickEvent",click);R.call(line,"setStyle",style);R.call(p,"displayClientMessage",line,false);Network.send(p,c.kind,0);}
 public static void start(Object p,Cycle c,boolean comfort,Object seat){if(!c.start(comfort))return;if(comfort)SEATS.put(p,seat);Network.send(p,c.kind,c.active);Content.sound(R.call(p,"level"),R.call(p,"blockPosition"),c.kind==1?"needs_urinate":"needs_defecate",.6f);save(p,c);}
 static void release(Object p){if(FORCED.remove(p)){if(R.call(p,"getForcedPose")==R.get(R.type("net.minecraft.world.entity.Pose"),"CROUCHING"))R.call(p,"setForcedPose",PREVIOUS_POSE.remove(p));R.call(p,"setShiftKeyDown",false);}SEATS.remove(p);}
 static void effect(Object p,String name,int ticks,int amp){R.call(p,"addEffect",R.make("net.minecraft.world.effect.MobEffectInstance",R.get(R.type("net.minecraft.world.effect.MobEffects"),name),ticks,amp,false,false,true));}
 static boolean disabled(Object p){return !R.yes(R.call(p,"isAlive"))||R.yes(R.call(p,"isCreative"))||R.yes(R.call(p,"isSpectator"));}
 static boolean busy(Object p){if(R.yes(R.call(p,"isSleeping")))return true;if(!aidChecked){aidChecked=true;try{aid=Class.forName("dev.zomboid.firstaid.DownedSupport");}catch(ClassNotFoundException absent){}}return aid!=null&&R.yes(R.call(aid,"down",p));}
 public static void tick(Object event){Object p=R.call(event,"getEntity"),w=R.call(p,"level");if(R.yes(R.call(w,"isClientSide")))return;try{Cycle c=get(p);if(disabled(p)){if(c.active>0){c.cancel();release(p);}if(SYNCED.remove(p))Network.send(p,0,0);save(p,c);return;}if(busy(p)){if(c.active>0){c.cancel();release(p);Network.send(p,c.kind,0);}return;}
  if(SYNCED.add(p)){if(c.kind>0)prompt(p,c);else Network.send(p,0,0);}int result=c.tick();if(result==1)prompt(p,c);if(result==2)start(p,c,false,null);if(c.active>0){if(c.kind==2){if(FORCED.add(p))PREVIOUS_POSE.put(p,R.call(p,"getForcedPose"));R.call(p,"setForcedPose",R.get(R.type("net.minecraft.world.entity.Pose"),"CROUCHING"));R.call(p,"setShiftKeyDown",true);}Object seat=SEATS.get(p);if(c.comfort&&c.active%10==0&&(seat==null||!seat.equals(Toilets.nearby(p,c.kind))))c.comfort=false;if(c.active%20==0)Network.send(p,c.kind,c.active);if(c.active%4==0)particles(p,c);if(c.active%10==0)text(p,"progress",true,(200-c.active)/2);}
  else if(result==3){boolean comfortable=c.comfort&&SEATS.get(p)!=null&&SEATS.get(p).equals(Toilets.nearby(p,3-c.nextKind));release(p);Network.send(p,0,0);text(p,"relieved",true);if(comfortable){effect(p,"REGENERATION",200,1);Content.sound(w,R.call(p,"blockPosition"),"toilet_flush",.8f);}else place(p);c.comfort=false;}
  else if(c.kind>0){if(c.grace%20==0){Object seat=Toilets.nearby(p,c.kind);if(seat!=null)start(p,c,true,seat);}if(c.grace%100==0)text(p,"remaining",true,(c.grace+19)/20);}
  if(c.active>0||c.kind>0||c.remaining%20==0)save(p,c);
 }catch(Throwable e){if(!warned){warned=true;R.warn("Doomsday needs tick",e);}}}
 static void particles(Object p,Cycle c){Object w=R.call(p,"level"),particle=c.kind==1?Content.PEE:Content.POOP;if(particle==null)return;double angle=Math.toRadians(((Number)R.get(p,"yBodyRot")).doubleValue()),fx=-Math.sin(angle),fz=Math.cos(angle),sign=c.kind==1?1:-1;double x=R.coord(p,"X")+fx*.28*sign,y=R.coord(p,"Y")+(c.kind==1?.75:.48),z=R.coord(p,"Z")+fz*.28*sign;for(int i=0;i<(c.kind==1?3:1);i++)R.call(w,"sendParticles",particle,x,y,z,0,fx*(c.kind==1?.12:-.03),-.06,fz*(c.kind==1?.12:-.03),1.);}
 static void place(Object p){/* Existing feces block is placed only on safe empty supported floor. */Cycle c=get(p);if(c.nextKind!=1)return;Object w=R.call(p,"level"),base=R.call(p,"blockPosition");for(int y=0;y>=-2;y--){Object pos=R.call(base,"offset",0,y,0);if(!R.yes(R.call(w,"hasChunkAt",pos)))continue;Object state=R.call(w,"getBlockState",pos),below=R.call(pos,"below");if(!R.yes(R.call(state,"isAir"))||!R.yes(R.call(R.call(w,"getBlockState",below),"isFaceSturdy",w,below,R.get(R.type("net.minecraft.core.Direction"),"UP"))))continue;Object blocks=R.get(R.type("net.mcreator.doomsdaydecoration.DoomsdayDecorationMod"),"BLOCKS_BY_ID");Object block=R.call(((Map<?,?>)blocks).get("shit"),"get");R.call(w,"setBlock",pos,R.call(block,"defaultBlockState"),3);return;}}
 public static int command(Object source,String action){Object p=R.call(source,"getPlayerOrException");if(disabled(p)||busy(p))return 0;Cycle c=get(p);if(c.kind==0){text(p,"not_due",true);return 0;}if(action.equals("aqui"))start(p,c,false,null);else if(action.equals("aguantar")){if(c.hold()){text(p,"held",false);save(p,c);}else text(p,"no_more_hold",true);}else if(action.equals("bano")){Object seat=Toilets.nearby(p,c.kind);if(seat!=null)start(p,c,true,seat);else text(p,"go_to_toilet",false);}return 1;}
 public static void commands(Object event){Class<?> commands=R.type("net.minecraft.commands.Commands"),cmd=R.type("com.mojang.brigadier.Command");Object root=R.call(commands,"literal","necesidades");for(String action:List.of("aqui","aguantar","bano")){Object child=R.call(commands,"literal",action);Object handler=java.lang.reflect.Proxy.newProxyInstance(cmd.getClassLoader(),new Class<?>[]{cmd},(proxy,method,args)->{if(method.getName().equals("run"))return command(R.call(args[0],"getSource"),action);if(method.getName().equals("toString"))return "DoomsdayNeedsCommand";return null;});R.call(child,"executes",handler);R.call(root,"then",child);}R.call(R.call(event,"getDispatcher"),"register",root);}
}
